import { SeedApiClient } from "../../src/Client";
import { mockServerPool } from "../mock-server/MockServerPool";
import { mockOAuth2 } from "./mockAuth";

describe("AuthClient", () => {
    test("getToken", async () => {
        const server = mockServerPool.createServer();
        mockOAuth2(server);

        const client = new SeedApiClient({
            maxRetries: 0,
            clientId: "client_id",
            clientSecret: "client_secret",
            environment: server.baseUrl,
        });
        const rawRequestBody = {
            client_id: "client_id",
            client_secret: "client_secret",
            scopes: "scopes",
            grant_type: "client_credentials",
            tenant: "tenant",
        };
        const rawResponseBody = { access_token: "access_token", expires_in: 1, refresh_token: "refresh_token" };

        server
            .mockEndpoint()
            .post("/token")
            .jsonBody(rawRequestBody)
            .respondWith()
            .statusCode(200)
            .jsonBody(rawResponseBody)
            .build();

        const response = await client.auth.getToken({
            client_id: "client_id",
            client_secret: "client_secret",
            scopes: "scopes",
            grant_type: "client_credentials",
            tenant: "tenant",
        });
        expect(response).toEqual(rawResponseBody);
    });

    test("refreshToken", async () => {
        const server = mockServerPool.createServer();
        mockOAuth2(server);

        const client = new SeedApiClient({
            maxRetries: 0,
            clientId: "client_id",
            clientSecret: "client_secret",
            environment: server.baseUrl,
        });
        const rawRequestBody = { refresh_token: "refresh_token", grant_type: "refresh_token" };
        const rawResponseBody = { access_token: "access_token", expires_in: 1, refresh_token: "refresh_token" };

        server
            .mockEndpoint()
            .post("/refresh")
            .jsonBody(rawRequestBody)
            .respondWith()
            .statusCode(200)
            .jsonBody(rawResponseBody)
            .build();

        const response = await client.auth.refreshToken({
            refresh_token: "refresh_token",
            grant_type: "refresh_token",
        });
        expect(response).toEqual(rawResponseBody);
    });
});
